for (let j = ECHOES; j >= 1; j--) {
  const px = pos(t - j * ECHO_GAP);
  drawGhost(px, 0.5 * (1 - (j - 1) / ECHOES));
}

const expo = SHUTTER / 360 / FPS;
for (let k = 0; k < SAMPLES; k++) {
  drawBall(pos(t - expo * k / (SAMPLES - 1)), alpha);
}

const mix = (j - 1) / (ECHOES - 1);
draw(warm, alpha * (1 - mix));
draw(cool, alpha * mix);
